    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn handles_empty_double_quoted_value() {
        let content = r#"KEY="""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_empty_single_quoted_value() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_are_not_stripped() {
        let content = "KEY=\"value'";
        let vars = EnvFileParser::parse(content).unwrap();
        // Mismatched quotes should be preserved as-is
        assert_eq!(vars.get("KEY"), Some(&"\"value'".to_string()));
    }

    #[test]
    fn mismatched_quotes_single_double_not_stripped() {
        let content = "KEY='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes_preserved() {
        let content = r#"KEY="it's a test""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes_preserved() {
        let content = r#"KEY='he said "hi"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"he said \"hi\"".to_string()));
    }

    #[test]
    fn unclosed_double_quote_preserved() {
        let content = "KEY=\"unclosed value";
        let vars = EnvFileParser::parse(content).unwrap();
        // No closing quote, so not treated as quoted
        assert_eq!(vars.get("KEY"), Some(&"\"unclosed value".to_string()));
    }

    #[test]
    fn unclosed_single_quote_preserved() {
        let content = "KEY='unclosed value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'unclosed value".to_string()));
    }

    #[test]
    fn only_closing_quote_not_stripped() {
        let content = "KEY=value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        // Doesn't start with quote, so not treated as quoted
        assert_eq!(vars.get("KEY"), Some(&"value\"".to_string()));
    }

    #[test]
    fn value_is_single_double_quote() {
        let content = "KEY=\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn value_is_single_single_quote() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn quoted_value_with_spaces_preserved() {
        let content = r#"KEY="  leading and trailing  ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    // --- Escaped character edge cases ---

    #[test]
    fn backslash_n_in_double_quotes_is_literal() {
        // Parser does not interpret escape sequences
        let content = r#"KEY="line\nbreak""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"line\nbreak".to_string()));
    }

    #[test]
    fn backslash_t_in_double_quotes_is_literal() {
        let content = r#"KEY="tab\there""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"tab\there".to_string()));
    }

    #[test]
    fn escaped_double_quote_in_double_quotes_is_literal() {
        // Parser does not process \" escapes — the backslash is preserved
        let content = r#"KEY="say \"hello\"""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say \"hello\"#.to_string()));
    }

    #[test]
    fn backslash_in_unquoted_value_is_literal() {
        let content = r"KEY=path\to\file";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\to\file".to_string()));
    }

    #[test]
    fn double_backslash_in_quotes_is_literal() {
        let content = r#"KEY="back\\slash""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"back\\slash".to_string()));
    }

    // --- Inline comment edge cases ---

    #[test]
    fn inline_comment_is_included_in_unquoted_value() {
        // Parser does not strip inline comments
        let content = "KEY=value # this is a comment";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is a comment".to_string())
        );
    }

    #[test]
    fn hash_in_double_quoted_value_preserved() {
        let content = r#"KEY="value # not a comment""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn hash_in_single_quoted_value_preserved() {
        let content = "KEY='value # not a comment'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    // --- Key edge cases ---

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn line_with_only_equals_produces_empty_key_and_value() {
        let content = "=";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn equals_with_only_value_produces_empty_key() {
        let content = "=some_value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"some_value".to_string()));
    }

    #[test]
    fn export_prefix_is_not_handled() {
        // Parser treats "export KEY" as the key name
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    // --- Whitespace edge cases ---

    #[test]
    fn whitespace_only_lines_are_skipped() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn leading_whitespace_on_line_is_trimmed() {
        let content = "  KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
