//!
//! This module provides functionality for parsing environment variable files
//! in the standard KEY=value format.

use anyhow::Result;
use std::collections::HashMap;
use std::path::Path;

/// Parses .env files into a map of environment variables.
///
/// # Supported Formats
///
/// - Simple: `KEY=value`
/// - Quoted: `KEY="value with spaces"` or `KEY='single quoted'`
/// - Empty: `KEY=`
/// - Comments: `# This is a comment`
/// - Whitespace around equals: `KEY = value`
/// - Values with equals signs: `URL=https://example.com?foo=bar`
///
/// # Example
///
/// ```
/// use bivvy::config::EnvFileParser;
///
/// let content = r#"
/// # Database config
/// DATABASE_URL=postgres://localhost/db
/// DEBUG="true"
/// EMPTY=
/// "#;
///
/// let vars = EnvFileParser::parse(content).unwrap();
/// assert_eq!(vars.get("DATABASE_URL"), Some(&"postgres://localhost/db".to_string()));
/// assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
/// assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
/// ```
pub struct EnvFileParser;

impl EnvFileParser {
    /// Parse an env file content string into a map of variables.
    pub fn parse(content: &str) -> Result<HashMap<String, String>> {
        let mut vars = HashMap::new();

        for line in content.lines() {
            let line = line.trim();

            // Skip empty lines and comments
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            // Parse KEY=value
            if let Some((key, value)) = Self::parse_line(line) {
                vars.insert(key, value);
            }
        }

        Ok(vars)
    }

    /// Parse a single line.
    fn parse_line(line: &str) -> Option<(String, String)> {
        let eq_pos = line.find('=')?;
        let key = line[..eq_pos].trim().to_string();
        let value = line[eq_pos + 1..].trim();

        // Handle quoted values
        let value = Self::unquote(value);

        Some((key, value))
    }

    /// Remove surrounding quotes from a value.
    fn unquote(value: &str) -> String {
        if (value.starts_with('"') && value.ends_with('"'))
            || (value.starts_with('\'') && value.ends_with('\''))
        {
            if value.len() >= 2 {
                value[1..value.len() - 1].to_string()
            } else {
                value.to_string()
            }
        } else {
            value.to_string()
        }
    }

    /// Load and parse an env file from a path.
    ///
    /// # Example
    ///
    /// ```no_run
    /// use bivvy::config::EnvFileParser;
    /// use std::path::Path;
    ///
    /// let vars = EnvFileParser::load(Path::new(".env")).unwrap();
    /// for (key, value) in &vars {
    ///     println!("{}={}", key, value);
    /// }
    /// ```
    pub fn load(path: &Path) -> Result<HashMap<String, String>> {
        let content = std::fs::read_to_string(path)?;
        Self::parse(&content)
    }

    /// Load and parse an env file, returning empty map if file doesn't exist.
    pub fn load_optional(path: &Path) -> Result<HashMap<String, String>> {
        if path.exists() {
            Self::load(path)
        } else {
            Ok(HashMap::new())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_simple_env_file() {
        let content = r#"
KEY1=value1
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY1"), Some(&"value1".to_string()));
        assert_eq!(vars.get("KEY2"), Some(&"value2".to_string()));
    }

    #[test]
    fn skips_comments() {
        let content = r#"
# This is a comment
KEY=value
# Another comment
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 1);
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn handles_quoted_values() {
        let content = r#"
DOUBLE="double quoted"
SINGLE='single quoted'
UNQUOTED=no quotes
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("DOUBLE"), Some(&"double quoted".to_string()));
        assert_eq!(vars.get("SINGLE"), Some(&"single quoted".to_string()));
        assert_eq!(vars.get("UNQUOTED"), Some(&"no quotes".to_string()));
    }

    #[test]
    fn handles_empty_values() {
        let content = "EMPTY=";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("EMPTY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_values_with_equals() {
        let content = "URL=https://example.com?foo=bar";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(
            vars.get("URL"),
            Some(&"https://example.com?foo=bar".to_string())
        );
    }

    #[test]
    fn handles_whitespace_around_equals() {
        let content = "KEY = value with spaces";

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("KEY"), Some(&"value with spaces".to_string()));
    }

    #[test]
    fn skips_empty_lines() {
        let content = r#"
KEY1=value1

KEY2=value2

"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn handles_lines_without_equals() {
        let content = r#"
KEY1=value1
invalid line without equals
KEY2=value2
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn load_optional_returns_empty_for_missing_file() {
        let result = EnvFileParser::load_optional(Path::new("/nonexistent/path/.env"));

        assert!(result.is_ok());
        assert!(result.unwrap().is_empty());
    }

    #[test]
    fn complex_env_file() {
        let content = r#"
# Application settings
APP_NAME=MyApp
DEBUG=true

# Database
DATABASE_URL="postgres://user:pass@localhost:5432/db"

# API Keys
API_KEY='secret-key-123'
WEBHOOK_URL=https://api.example.com/webhook?token=abc&id=123
"#;

        let vars = EnvFileParser::parse(content).unwrap();

        assert_eq!(vars.get("APP_NAME"), Some(&"MyApp".to_string()));
        assert_eq!(vars.get("DEBUG"), Some(&"true".to_string()));
        assert_eq!(
            vars.get("DATABASE_URL"),
            Some(&"postgres://user:pass@localhost:5432/db".to_string())
        );
        assert_eq!(vars.get("API_KEY"), Some(&"secret-key-123".to_string()));
        assert!(vars.get("WEBHOOK_URL").unwrap().contains("token=abc"));
    }

    // --- Quote edge cases ---

    #[test]
    fn handles_empty_double_quoted_value() {
        let content = r#"KEY="""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn handles_empty_single_quoted_value() {
        let content = "KEY=''";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn mismatched_quotes_are_not_stripped() {
        let content = "KEY=\"value'";
        let vars = EnvFileParser::parse(content).unwrap();
        // Mismatched quotes should be preserved as-is
        assert_eq!(vars.get("KEY"), Some(&"\"value'".to_string()));
    }

    #[test]
    fn mismatched_quotes_single_double_not_stripped() {
        let content = "KEY='value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'value\"".to_string()));
    }

    #[test]
    fn single_quotes_inside_double_quotes_preserved() {
        let content = r#"KEY="it's a test""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"it's a test".to_string()));
    }

    #[test]
    fn double_quotes_inside_single_quotes_preserved() {
        let content = r#"KEY='he said "hi"'"#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"he said \"hi\"".to_string()));
    }

    #[test]
    fn unclosed_double_quote_preserved() {
        let content = "KEY=\"unclosed value";
        let vars = EnvFileParser::parse(content).unwrap();
        // No closing quote, so not treated as quoted
        assert_eq!(vars.get("KEY"), Some(&"\"unclosed value".to_string()));
    }

    #[test]
    fn unclosed_single_quote_preserved() {
        let content = "KEY='unclosed value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'unclosed value".to_string()));
    }

    #[test]
    fn only_closing_quote_not_stripped() {
        let content = "KEY=value\"";
        let vars = EnvFileParser::parse(content).unwrap();
        // Doesn't start with quote, so not treated as quoted
        assert_eq!(vars.get("KEY"), Some(&"value\"".to_string()));
    }

    #[test]
    fn value_is_single_double_quote() {
        let content = "KEY=\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
    }

    #[test]
    fn value_is_single_single_quote() {
        let content = "KEY='";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"'".to_string()));
    }

    #[test]
    fn quoted_value_with_spaces_preserved() {
        let content = r#"KEY="  leading and trailing  ""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"  leading and trailing  ".to_string())
        );
    }

    // --- Escaped character edge cases ---

    #[test]
    fn backslash_n_in_double_quotes_is_literal() {
        // Parser does not interpret escape sequences
        let content = r#"KEY="line\nbreak""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"line\nbreak".to_string()));
    }

    #[test]
    fn backslash_t_in_double_quotes_is_literal() {
        let content = r#"KEY="tab\there""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"tab\there".to_string()));
    }

    #[test]
    fn escaped_double_quote_in_double_quotes_is_literal() {
        // Parser does not process \" escapes — the backslash is preserved
        let content = r#"KEY="say \"hello\"""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r#"say \"hello\"#.to_string()));
    }

    #[test]
    fn backslash_in_unquoted_value_is_literal() {
        let content = r"KEY=path\to\file";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"path\to\file".to_string()));
    }

    #[test]
    fn double_backslash_in_quotes_is_literal() {
        let content = r#"KEY="back\\slash""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"back\\slash".to_string()));
    }

    // --- Inline comment edge cases ---

    #[test]
    fn inline_comment_is_included_in_unquoted_value() {
        // Parser does not strip inline comments
        let content = "KEY=value # this is a comment";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # this is a comment".to_string())
        );
    }

    #[test]
    fn hash_in_double_quoted_value_preserved() {
        let content = r#"KEY="value # not a comment""#;
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    #[test]
    fn hash_in_single_quoted_value_preserved() {
        let content = "KEY='value # not a comment'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(
            vars.get("KEY"),
            Some(&"value # not a comment".to_string())
        );
    }

    // --- Key edge cases ---

    #[test]
    fn duplicate_keys_last_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    #[test]
    fn line_with_only_equals_produces_empty_key_and_value() {
        let content = "=";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"".to_string()));
    }

    #[test]
    fn equals_with_only_value_produces_empty_key() {
        let content = "=some_value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get(""), Some(&"some_value".to_string()));
    }

    #[test]
    fn export_prefix_is_not_handled() {
        // Parser treats "export KEY" as the key name
        let content = "export KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    // --- Whitespace edge cases ---

    #[test]
    fn whitespace_only_lines_are_skipped() {
        let content = "KEY1=a\n   \n\t\nKEY2=b";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.len(), 2);
    }

    #[test]
    fn leading_whitespace_on_line_is_trimmed() {
        let content = "  KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn trailing_whitespace_on_unquoted_value_is_trimmed() {
        let content = "KEY=value   ";
        let vars = EnvFileParser::parse(content).unwrap();
        // line is trimmed, then value is trimmed
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    // --- Unicode and special characters ---

    #[test]
    fn unicode_in_values() {
        let content = "GREETING=こんにちは";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
    fn unicode_in_quoted_values() {
        let content = "GREETING=\"café résumé\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"café résumé".to_string()));
    }

    #[test]
    fn multiple_equals_in_value() {
        let content = "FORMULA=a=b=c=d";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("FORMULA"), Some(&"a=b=c=d".to_string()));
    }

    // --- File I/O ---

    #[test]
    fn load_reads_file_from_disk() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "FROM_FILE=yes\nANOTHER=42").unwrap();

        let vars = EnvFileParser::load(&env_path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"yes".to_string()));
        assert_eq!(vars.get("ANOTHER"), Some(&"42".to_string()));
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = tempfile::TempDir::new().unwrap();
        let env_path = dir.path().join(".env");
        std::fs::write(&env_path, "KEY=value").unwrap();

        let vars = EnvFileParser::load_optional(&env_path).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    // --- Empty / edge inputs ---

    #[test]
    fn empty_input_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_comments_returns_empty_map() {
        let content = "# comment 1\n# comment 2\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn only_blank_lines_returns_empty_map() {
        let content = "\n\n\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }
}
